// Validar se é evento PIX_PAYMENT_CONFIRMED
const data = items[0].json;

if (data.event !== 'PIX_PAYMENT_CONFIRMED') {
  throw new Error('Evento inválido: ' + data.event);
}

// Validar campos obrigatórios
if (!data.user_id || !data.payment_id || !data.amount) {
  throw new Error('Dados obrigatórios ausentes');
}

// Formatar dados para o próximo nó
return [{
  json: {
    user_id: data.user_id,
    payment_id: data.payment_id,
    amount: data.amount,
    timestamp: data.timestamp,
    formatted_amount: `R$ ${data.amount.toFixed(2).replace('.', ',')}`,
    formatted_date: new Date(data.timestamp).toLocaleString('pt-BR')
  }
}];

// Simular busca de dados do usuário
// Em produção, conectar com banco de dados real

const userId = items[0].json.user_id;

// Mock de dados do usuário
const mockUsers = {
  'user_123': {
    name: 'João Silva',
    email: 'joao@exemplo.com',
    phone: '(11) 99999-9999'
  },
  'user_456': {
    name: 'Maria Santos',
    email: 'maria@exemplo.com', 
    phone: '(11) 88888-8888'
  }
};

const userData = mockUsers[userId] || {
  name: 'Cliente',
  email: 'cliente@exemplo.com',
  phone: '(11) 00000-0000'
};

return [{
  json: {
    ...items[0].json,
    user_name: userData.name,
    user_email: userData.email,
    user_phone: userData.phone
  }
}];

// Log de sucesso
const data = items[0].json;

console.log('✅ Email de confirmação PIX enviado:', {
  user_id: data.user_id,
  user_email: data.user_email,
  payment_id: data.payment_id,
  amount: data.amount,
  timestamp: new Date().toISOString()
});

return [{
  json: {
    status: 'success',
    message: 'Email enviado com sucesso',
    user_id: data.user_id,
    payment_id: data.payment_id,
    processed_at: new Date().toISOString()
  }
}];

// Log de erro - usuário não encontrado
const data = items[0].json;

console.error('❌ Usuário não encontrado para PIX:', {
  user_id: data.user_id,
  payment_id: data.payment_id,
  amount: data.amount,
  timestamp: new Date().toISOString()
});

return [{
  json: {
    status: 'error',
    message: 'Usuário não encontrado',
    user_id: data.user_id,
    payment_id: data.payment_id,
    error_at: new Date().toISOString()
  }
}];

// Resposta final do webhook
return [{
  json: {
    received: true,
    processed_at: new Date().toISOString(),
    message: 'Webhook PIX processado com sucesso'
  }
}];
